import sys
import math

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        q = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(q):
        try:
            a_str = next(iterator)
            a = int(a_str)
        except StopIteration:
            break

        best_gcd = 0

        msb = a.bit_length()

        for k in range(msb - 1, 0, -1):
            g = 1 << k

            if g >= a:
                continue

            r = a % g
            if r == 0:
                continue

            needed = g - r

            if needed < a and needed > 0:
                x = a ^ needed
                y = a & needed

                if (x % g == 0) and (y % g == 0):
                    best_gcd = g
                    break

        results.append(str(best_gcd))

    sys.stdout.write('\n'.join(results) + '\n')

if __name__ == "__main__":
    solve()
